/**
 * @fileoverview The host's pinning helper (#714): pins each function in a call's arguments to the current caller with
 * `api.slothlet.lockCaller`.
 * @module owner-host/pins
 */

/**
 * Pin every function argument.
 * @param {object} api - The bound api the host's `slothlet()` call returned.
 * @param {unknown[]} args - The call's arguments.
 * @returns {unknown[]} The arguments, functions pinned.
 */
export function pinArgs(api, args) {
	return args.map((value) => (typeof value === "function" ? api.slothlet.lockCaller(value) : value));
}
